(()=>{'use strict';const ID='lw-3d-globe';const style=document.createElement('style');style.textContent=`#${ID}{position:relative;height:490px;border-radius:14px;overflow:hidden;background:radial-gradient(#173367,#050c26);color:white}#${ID} .globe{height:100%}#${ID} .top{position:absolute;top:15px;left:18px;z-index:2;font-size:22px;font-weight:700;pointer-events:none}#${ID} .bottom{position:absolute;bottom:10px;left:10px;right:10px;z-index:2;background:#091630dd;border:1px solid #6177a3;padding:12px;border-radius:9px;font-size:13px}#${ID} button{position:absolute;right:14px;top:14px;z-index:3;background:#172d58;color:white;border:1px solid #8da3cf;border-radius:8px;padding:9px 14px;cursor:pointer}@media(max-width:600px){#${ID}{height:370px}#${ID} .top{font-size:16px}}`;document.head.appendChild(style);
const known=[['Шэньчжэнь',22.5431,114.0579],['Минск',53.9006,27.559],['Нинбо',29.8683,121.544],['Shenzhen',22.5431,114.0579],['Minsk',53.9006,27.559],['Ningbo',29.8683,121.544]];
let busy=false;let failed=false;async function load(){if(window.Globe)return;const urls=['https://cdn.jsdelivr.net/npm/globe.gl/dist/globe.gl.min.js','https://unpkg.com/globe.gl/dist/globe.gl.min.js','https://cdnjs.cloudflare.com/ajax/libs/globe.gl/2.33.1/globe.gl.min.js'];for(const url of urls){try{await new Promise((ok,no)=>{const script=document.createElement('script');script.src=url;script.onload=()=>window.Globe?ok():no(new Error('Globe missing'));script.onerror=no;document.head.append(script);setTimeout(()=>no(new Error('timeout')),9000)});if(window.Globe)return}catch(e){}}throw Error('3D library unavailable')}
async function mount(){if(busy||failed)return;const h=[...document.querySelectorAll('h1,h2,h3,h4,strong')].find(x=>x.textContent.trim()==='Живая карта логистики');if(!h)return;const section=h.closest('section,article')||h.parentElement?.parentElement;if(!section||section.querySelector('#'+ID))return;const iframe=[...section.querySelectorAll('iframe')].find(x=>/yandex|map/i.test(x.src||''));if(!iframe)return;
const raw=section.textContent||'';let pts=[];for(const k of known)if(raw.toLowerCase().includes(k[0].toLowerCase())&&!pts.some(p=>p.lat===k[1]&&p.lng===k[2]))pts.push({name:k[0],lat:k[1],lng:k[2]});if(pts.length<2)return;
const a=pts.find(x=>x.name==='Шэньчжэнь'||x.name==='Shenzhen'),b=pts.find(x=>x.name==='Минск'||x.name==='Minsk');if(b){const start=a||pts.find(x=>x.name==='Нинбо'||x.name==='Ningbo');if(start)pts=[start,...pts.filter(x=>x!==start&&x!==b),b]}const host=document.createElement('div');host.id=ID;host.innerHTML='<div class="top">3D · Живая карта логистики</div><button type="button">Вернуть 2D</button><div class="globe"></div><div class="bottom"></div>';iframe.before(host);iframe.style.display='none';host.querySelector('.bottom').textContent=pts.map((p,i)=>((i+1)+'. '+p.name)).join('  →  ')+' · Схематическое соединение точек, не точная ЖД-трасса';host.querySelector('button').onclick=()=>{iframe.style.display='';host.remove()};
busy=true;try{await load();if(!host.isConnected)return;const el=host.querySelector('.globe');if(typeof window.Globe!=='function')throw Error('Globe is not callable');const g=window.Globe()(el).globeImageUrl('https://unpkg.com/three-globe/example/img/earth-blue-marble.jpg').backgroundColor('rgba(0,0,0,0)').pointsData(pts).pointLat('lat').pointLng('lng').pointColor(()=>'#ffcb23').pointRadius(.5).pointAltitude(.025).pointLabel(p=>p.name).arcsData(pts.slice(1).map((p,i)=>({startLat:pts[i].lat,startLng:pts[i].lng,endLat:p.lat,endLng:p.lng}))).arcColor(()=>['#ffce26','#f8eaa2']).arcDashLength(.6).arcDashGap(.12).arcDashAnimateTime(3600);g.width(el.clientWidth).height(el.clientHeight);g.pointOfView({lat:40,lng:70,altitude:2.4},1200);if(window.ResizeObserver)new ResizeObserver(()=>{if(el.isConnected)g.width(el.clientWidth).height(el.clientHeight)}).observe(el)}catch(e){failed=true;iframe.style.removeProperty('display');host.remove();console.warn('3D globe unavailable, original 2D restored',e)}finally{busy=false}}
new MutationObserver(()=>{if(!busy)mount()}).observe(document.body,{childList:true,subtree:true});mount()})();